#define main original_floyd_main
#include "../floydwarshall2-cuda/main.cu"
#undef main
#include "study_support.h"
#include <chrono>
struct FGpu {int*p;size_t n;FGpu(const std::vector<int>&input):n(input.size()){std::vector<int>a(n+2*FG,FGUARD);std::copy(input.begin(),input.end(),a.begin()+FG);if(cudaMalloc(&p,a.size()*4)!=cudaSuccess)throw std::runtime_error("allocation");if(uintptr_t(p+FG)%256)throw std::runtime_error("alignment");if(cudaMemcpy(p,a.data(),a.size()*4,cudaMemcpyHostToDevice)!=cudaSuccess)throw std::runtime_error("upload");}int*data(){return p+FG;}~FGpu(){cudaFree(p);}std::vector<int>read(){std::vector<int>a(n+2*FG);if(cudaMemcpy(a.data(),p,a.size()*4,cudaMemcpyDeviceToHost)!=cudaSuccess)throw std::runtime_error("readback");if(!std::all_of(a.begin(),a.begin()+FG,[](int x){return x==FGUARD;})||!std::all_of(a.end()-FG,a.end(),[](int x){return x==FGUARD;}))throw std::runtime_error("exact guard");return a;}void check(const std::vector<int>&want,const char*name){auto a=read();f_assert_equal(std::vector<int>(a.begin()+FG,a.end()-FG),want,name);}};
static void f_wait(){auto e=cudaDeviceSynchronize();if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
__global__ void f_observe(int*out,int n,int e,int u,int r){if(threadIdx.x==0){out[0]=n;out[1]=e;out[2]=u;out[3]=r;}}
static void f_compute(FCase const&c,int*a,int*kr,int*kc){int sub=c.u/64,sm=sub-1;FW0_64<<<1,1024>>>(a,c.u,kr,kc);if(sub>1)for(int x=0;x<sub;x++){FWrowcol_64<<<2*sm,1024>>>(a,c.u,kr,kc,x,sm);FWrem_64<<<sm*sm,1024>>>(a,c.u,kr,kc,x,sm);}}
static void f_execute(int trial,const std::vector<FCase>&cases){std::vector<int>prefix,post;double seconds=0;size_t words=0;for(size_t ci=0;ci<cases.size();ci++){auto const&c=cases[ci];FGpu idx(c.idx),nei(c.nei),wt(c.wt),a(std::vector<int>(c.u*c.u,FINF)),kr(std::vector<int>(c.u*c.u,FINF)),kc(std::vector<int>(c.u*c.u,FINF)),params(std::vector<int>(4,0));ECLgraph g{c.n,c.e,idx.data(),nei.data(),wt.data()};f_observe<<<1,32>>>(params.data(),c.n,c.e,c.u,c.r);f_wait();idx.check(c.idx,"actual CSRidx");nei.check(c.nei,"actual CSRnei");wt.check(c.wt,"actual CSRweight");params.check({c.n,c.e,c.u,c.r},"actual scalar inputs");for(auto*o:{&a,&kr,&kc})o->check(std::vector<int>(c.u*c.u,FINF),"actual initial matrices");if(trial)for(auto*o:{&idx,&nei,&wt,&a,&kr,&kc,&params})f_append(prefix,o->read());
 f_wait();auto t=std::chrono::steady_clock::now();for(int rep=0;rep<c.r;rep++){init1<<<(c.u*c.u+1023)/1024,1024>>>(c.n,a.data(),c.u);init2<<<(c.n+1023)/1024,1024>>>(g,a.data(),c.u);}f_wait();double init=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/c.r;
 t=std::chrono::steady_clock::now();for(int rep=0;rep<c.r;rep++)f_compute(c,a.data(),kr.data(),kc.data());f_wait();double compute=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/c.r;seconds+=init+compute;
 idx.check(c.idx,"readonly CSRidx");nei.check(c.nei,"readonly CSRnei");wt.check(c.wt,"readonly CSRweight");params.check({c.n,c.e,c.u,c.r},"readonly parameters");a.check(c.oracle,"independent full Dijkstra APSP");kr.check(c.oracle,"independent final rowworkspace");std::vector<int>cols(c.u*c.u);for(int i=0;i<c.u;i++)for(int j=0;j<c.u;j++)cols[i*c.u+j]=c.oracle[((i/64)*64+j%64)*c.u+(j/64)*64+i%64];kc.check(cols,"independent blocktranspose columnworkspace");if(trial){for(auto*o:{&idx,&nei,&wt,&a,&kr,&kc,&params})f_append(post,o->read());printf("STUDY_REGION trial%d case%zu init_mean_s%.12g compute_mean_s%.12g repeat%d\n",trial,ci,init,compute,c.r);}}
 if(trial){if(prefix.size()!=post.size())throw std::runtime_error("artifact layout");words=prefix.size()+post.size();std::string name="floydwarshall2_trial"+std::to_string(trial)+".bin";std::ofstream f(name,std::ios::binary);f.write(reinterpret_cast<char*>(prefix.data()),prefix.size()*4);f.write(reinterpret_cast<char*>(post.data()),post.size()*4);f.close();if(!f)throw std::runtime_error("artifact write");printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"jit_excluded\":true,\"timing_region\":\"sum7_source_init_and_compute_repeat3_region_means\",\"internal_repeats\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,words,name.c_str(),words);fflush(stdout);}}
int main(){try{auto cases=f_cases();puts("ECL_APSP_STUDY named7graphs original64tile1024threads sourceR3closedstatepipeline");fflush(stdout);f_execute(0,cases);for(int t=1;t<=5;t++)f_execute(t,cases);}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
